  (citation_id,entity_id,source_id,work_title,locus,quote,translator,translation_year,source_url,original_text_url,evidence_grade,evidence_note,needs_review,review_reason,verified_on,verify_method,display_order)
VALUES
('CIT_LAT_BARSAFAEL_TSOL','ENT_LAT_BARSAFAEL','SRC_TESTAMENT_SOLOMON','The Testament of Solomon','Testament of Solomon','And the second said: "I am called Barsafael, and I cause those who are subject to my hour to feel the pain of migraine. If only I hear the words, ''Gabriel, imprison Barsafael,'' at once I retreat." 75. The third said: "I am called Arotosael. I do harm to eyes, and grievously injure them. Only let me hear the words, ''Uriel, imprison Aratosael'' (sic), at once I retreat . . . . . 1 " 1. There seems to be a lacuna here.','F. C. Conybeare',1898,'https://www.esotericarchives.com/solomon/testamen.htm',NULL,'primary-verbatim',NULL,true,'Located by name in the Testament of Solomon (Conybeare); verify the section.',DATE '2026-06-25','name-anchored + substring gate against Conybeare 1898 text',1),
('CIT_LAT_METATHIAX_TSOL','ENT_LAT_METATHIAX','SRC_TESTAMENT_SOLOMON','The Testament of Solomon','Testament of Solomon','The tenth said: "I am called Metathiax. I cause the reins to ache. If I hear the words, ''Adonael, imprison Metathiax,'' I at once retreat." 82. The eleventh said: "I am called Katanikotael.','F. C. Conybeare',1898,'https://www.esotericarchives.com/solomon/testamen.htm',NULL,'primary-verbatim',NULL,true,'Located by name in the Testament of Solomon (Conybeare); verify the section.',DATE '2026-06-25','name-anchored + substring gate against Conybeare 1898 text',1),
('CIT_LAT_HEPHESIMIRETH_TSOL','ENT_LAT_HEPHESIMIRETH','SRC_TESTAMENT_SOLOMON','The Testament of Solomon','Testament of Solomon','The thirty-first said: "I am called Hephesimireth, and cause lingering disease. If you throw salt, rubbed in the hand, into oil and smear it on the patient, saying: ''Seraphim, Cherubim, help me!'' I at once retire." 102. The thirty-second said: "I am called Ichthion. I paralyze muscles and contuse them. If I hear ''Adonaeth, help!'' I at once retire." 103. The thirty-third said: "I am called Agchonion.','F. C. Conybeare',1898,'https://www.esotericarchives.com/solomon/testamen.htm',NULL,'primary-verbatim',NULL,true,'Located by name in the Testament of Solomon (Conybeare); verify the section.',DATE '2026-06-25','name-anchored + substring gate against Conybeare 1898 text',1),
('CIT_NORDRI_PEDDA','ENT_NOR_NORDRI','SRC_POETIC_EDDA','The Poetic Edda (Voluspa)','Voluspa (Dvergatal)','Nyi and Nidi, Nordri and Sudri, Austri and Vestri, Althiof, Dvalin Nar and Nain, Niping, Dain, Bivor, Bavor, Bombur, Nori, An and Anar, Ai, Miodvitnir, 12. Veig and Gandalf, Vindalf, Thrain, Thekk and Thorin, Thror, Vitr, and Litr, Nur and Nyrad, Regin and Radsvid. Now of the dwarfs I have rightly told. 13. Fili, Kili, Fundin, Nali, Hepti, Vili, Hanar, Svior, Billing, Bruni, Bild, Buri, Frar, Hornbori, Fraeg and Loni, Aurvang, Iari, Eikinskialdi.','Benjamin Thorpe',1866,'https://www.gutenberg.org/ebooks/14726',NULL,'primary-verbatim',NULL,true,'Located by name in the Dvergatal of the Voluspa (Thorpe); verify the stanza.',DATE '2026-06-25','name-anchored + substring gate against Thorpe Poetic Edda (Gutenberg #14726)',1),
